import { Suspense } from 'react'
import StatsCards from '@/components/dashboard/StatsCards'
import ChartsSection from '@/components/dashboard/ChartsSection'
import DashboardLoading from './loading'
import Navbar from '@/components/Navbar'

async function getInsights() {
  const baseUrl = process.env.NEXT_PUBLIC_URL || 'http://localhost:3000'
  
  try {
    const response = await fetch(`${baseUrl}/api/insights`, {
      cache: 'no-store',
    })
    
    if (!response.ok) {
      throw new Error('Failed to fetch insights')
    }
    
    return response.json()
  } catch (error) {
    console.error('Error fetching insights:', error)
    // Return default values on error
    return {
      totalBooks: 0,
      indonesianBooks: 0,
      internationalBooks: 0,
      averageRating: 0,
      averagePages: 0,
      yearRange: {
        min: new Date().getFullYear(),
        max: new Date().getFullYear(),
      },
      topSubjects: [],
      languageDistribution: [],
    }
  }
}

export default async function DashboardPage() {
  const insights = await getInsights()

  return (
    <>
      <Navbar />
      <div className="min-h-screen pt-24 pb-20">
        <div className="container">
          {/* Header */}
          <div className="mb-16">
            <h1 className="text-6xl md:text-7xl font-bold tracking-tighter mb-4">
              Insights <span className="text-accent">Dashboard</span>
            </h1>
            <p className="text-xl text-midnight/60">
              Explore patterns and trends in our book collection
            </p>
          </div>

          {/* Stats Cards */}
          <Suspense fallback={<DashboardLoading />}>
            <StatsCards insights={insights} />
          </Suspense>

          {/* Charts Section */}
          <Suspense fallback={<div className="h-96 animate-pulse bg-midnight/5 rounded-3xl" />}>
            <ChartsSection insights={insights} />
          </Suspense>
        </div>
      </div>
    </>
  )
}
